-- 0070_zh_restore_dropped_senses.sql
-- Restores the Chinese senses the dictionary import dropped.
--
-- CC-CEDICT gives one line per reading, and a simplified form often has several:
-- "水 水 [Shui3] /surname Shui/Shui ethnic group/" and "水 水 [shui3] /water/.../". The
-- pipeline keyed entries on the simplified form and built each one from the first line only
-- (zhesen-pipeline `pipeline/zh_build.py`, `first = entries[0]`). Measured against the CEDICT
-- copy the import read, all 4,043 zh entries that have senses hold exactly that first line.
-- That first line is often a capitalised reading or a variant pointer: 120 entries such as
-- 水, 三, 国 and 山 kept only a surname, 成功 only a town in Taiwan, 和 and 从 only "variant
-- of", and words with two readings kept the rarer one: 行 háng without xíng, 说 shuì without
-- shuō, 重 chóng without zhòng.
--
-- Every other line of CC-CEDICT (release 2026-09-26) for the same simplified form is added:
-- 2,275 senses on 455 entries, 2 of which (埋头苦干, 汗流浃背) held no sense at all. Glosses
-- that only point at another headword or reading ("variant of ...", "used in ...", "Taiwan
-- pr. [...]") are left out, 174 of them, as are 59 the entry already holds. gloss_vi is
-- written for this migration.
--
-- The reading a learner meets first comes first: the one HSK 3.0 lists at the lowest level,
-- else the held line when it is an ordinary word, else the first ordinary line. Senses then
-- run: that reading, the other ordinary readings, variant pointers, surnames and places.
-- Held senses keep their ids and move. For the 351 entries whose first reading changes,
-- attributes.pinyin and the zh-pinyin pronunciation follow it (276 entries: 水 Shuǐ to
-- shuǐ, 行 háng to xíng), and so does the traditional form (88 entries: 从 gains 從, 和 drops
-- 咊).
--
-- lex.gloss_terms is rebuilt by its triggers. Every statement is idempotent against the
-- target state.
--
-- TO ROLL BACK: remove the lex.senses rows inserted below by id, then restore sense_order,
-- attributes.pinyin, traditional and the zh-pinyin ipa of the listed entries from a backup.
insert into lex.senses
  (id, entry_id, sense_order, gloss_en, gloss_vi, gloss_vi_is_mt, source_id, provenance)
